import React from "react";
import "./styles.scss";
import { Upload } from "antd";
import { CloudArrowUp } from "react-bootstrap-icons";

const allowedAccepts = {
  image: ".png,.jpg,.jpeg",
  audio: "audio/*",
  video: "video/*",
  pdf: ".pdf",
  excel: "",
  doc: ".doc,.docx,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document",
};

const UploadDocumentCard = ({
  setfileList,
  multiple,
  files = [],
  accept = Object.keys(allowedAccepts),
}) => {
  const { Dragger } = Upload;
  let fileTypes = "";
  if (accept.length < 1) {
    fileTypes = Object.values(allowedAccepts).join(",");
  } else {
    fileTypes = accept.map((type) => allowedAccepts[type]).join(",");
  }

  const props = {
    name: "file",
    fileList: files,
    multiple: multiple === undefined ? true : multiple,
    beforeUpload: () => false,
    onChange: (info) => {
      console.log(info.fileList);
      setfileList(info.fileList);
    },
    accept: fileTypes,
  };

  function hidenewCreativeTab() {
    document
      .querySelector(".upload-older-creative")
      .style.setProperty("display", "none", "important");
  }

  return (
    <Dragger {...props}>
      <p className="ant-upload-drag-icon">
        {/* <InboxOutlined /> */}
        <CloudArrowUp size="24" style={{ verticalAlign: "middle" }} />
      </p>
      <p className="upload-text" onClick={hidenewCreativeTab}>
        Drag a image/document here or Browse
      </p>
      {/* <div className="mb-10">- or -</div>
      <button  className="upload-btn">Select a photo from your computer</button> */}
    </Dragger>
  );
};

export default UploadDocumentCard;
